    public static function callingCode(string $country): ?string
    {
        return self::NUMBERING_PLANS[$country][0] ?? null;
    }

    /**
     * @return array{country: string, number: ?string}
     */
    public static function split(?string $phone, ?string $country = null): array
    {
        $country = Countries::normalize($country);
        $country = isset(self::NUMBERING_PLANS[$country]) ? $country : 'RO';
        $phone = trim((string) $phone);

        if ($phone === '') {
            return ['country' => $country, 'number' => null];
        }

        if (! preg_match('/^(?:\+|00)/', $phone) || ! preg_match('/^\+?[0-9\s().-]+$/D', $phone)) {
            return ['country' => $country, 'number' => $phone];
        }

        $digits = preg_replace('/\D/', '', preg_replace('/^00/', '', $phone));
        $countries = array_unique([$country, 'US', ...array_keys(self::NUMBERING_PLANS)]);

        foreach ($countries as $candidate) {
            $callingCode = self::callingCode($candidate);

            if (! str_starts_with($digits, $callingCode)) {
                continue;
            }

            $number = substr($digits, strlen($callingCode));

            if (self::normalizeNational($number, $candidate) !== null) {
                return ['country' => $candidate, 'number' => $number];
            }
        }

        return ['country' => $country, 'number' => $phone];
    }

    public static function normalize(?string $phone, ?string $country): ?string
    {
        $phone = trim((string) $phone);

        if ($phone === '' || ! isset(self::NUMBERING_PLANS[$country])) {
            return null;
        }

        if (! preg_match('/^\+?[0-9\s().-]+$/D', $phone)) {
            return null;
        }

        $callingCode = self::callingCode($country);
        $digits = preg_replace('/\D/', '', $phone);

        if (str_starts_with($phone, '+') || str_starts_with($phone, '00')) {
            $digits = str_starts_with($phone, '00') ? substr($digits, 2) : $digits;

            if (! str_starts_with($digits, $callingCode)) {
                return null;
            }

            $digits = substr($digits, strlen($callingCode));
        }

        $national = self::normalizeNational($digits, $country);

        if ($national === null || strlen($callingCode.$national) > 15) {
            return null;
        }

        return '+'.$callingCode.$national;
    }

    private static function normalizeNational(string $number, string $country): ?string
    {
        [, $trunkPrefix, $pattern, $lengths] = self::NUMBERING_PLANS[$country];
        $candidates = [$number];

        if ($trunkPrefix !== '' && str_starts_with($number, $trunkPrefix)) {
            $candidates[] = substr($number, strlen($trunkPrefix));
        }

        foreach ($candidates as $candidate) {
            if (in_array(strlen($candidate), $lengths, true) && preg_match('/^(?:'.$pattern.')$/D', $candidate)) {
                return $candidate;
            }
        }

        return null;
    }
